cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <cstdint>
using namespace cute;
template <typename T>
__global__ void min_reduce_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    int64_t Souter, int64_t Sreduce, int64_t Sinner_count,
    int64_t Sinner_full, int64_t inner_offset,
    int64_t st_outer, int64_t st_reduce, int64_t st_inner)
{
    // Flattened (outer, inner) index space with a grid-stride loop so a
    // single, robust launch configuration can cover arbitrary tensor
    // sizes without depending on grid.y limits, and so each SM keeps
    // issuing independent loads (better memory-level parallelism).
    //
    // Sinner_count is the number of inner-dimension columns handled by
    // this launch (which may be a sub-range / tail of the full inner
    // dimension when the bulk of it is processed by the vectorized
    // kernel instead). inner_offset shifts into the actual column space
    // of X/Y so the two launches cooperate to cover the full inner
    // extent exactly once.
    int64_t total = Souter * Sinner_count;
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)gridDim.x * blockDim.x;
    for (; idx < total; idx += stride) {
        int64_t outer = idx / Sinner_count;
        int64_t inner = idx - outer * Sinner_count;
        int64_t actual_inner = inner_offset + inner;
        int64_t base = outer * st_outer + actual_inner * st_inner;
        const T* __restrict__ ptr = X + base;
        // Use read-only cache path (__ldg) since X is never written by
        // this kernel; helps throughput for the strided reduction reads.
        // Use 4 independent accumulators to break the serial dependency
        // chain of the reduction loop, exposing more instruction-level
        // parallelism and better hiding global memory latency.
        T minval;
        if (Sreduce >= 16) {
            T m0  = __ldcs(ptr + 0  * st_reduce);
            T m1  = __ldcs(ptr + 1  * st_reduce);
            T m2  = __ldcs(ptr + 2  * st_reduce);
            T m3  = __ldcs(ptr + 3  * st_reduce);
            T m4  = __ldcs(ptr + 4  * st_reduce);
            T m5  = __ldcs(ptr + 5  * st_reduce);
            T m6  = __ldcs(ptr + 6  * st_reduce);
            T m7  = __ldcs(ptr + 7  * st_reduce);
            T m8  = __ldcs(ptr + 8  * st_reduce);
            T m9  = __ldcs(ptr + 9  * st_reduce);
            T m10 = __ldcs(ptr + 10 * st_reduce);
            T m11 = __ldcs(ptr + 11 * st_reduce);
            T m12 = __ldcs(ptr + 12 * st_reduce);
            T m13 = __ldcs(ptr + 13 * st_reduce);
            T m14 = __ldcs(ptr + 14 * st_reduce);
            T m15 = __ldcs(ptr + 15 * st_reduce);
            int64_t r = 16;
            // 16 independent accumulators further widen the
            // instruction-level / memory-level parallelism of the
            // strided reduction loop, issuing more concurrent
            // outstanding global loads per thread to better hide
            // the latency of the large-stride (non-vectorizable)
            // memory accesses inherent to this reduction shape.
            #pragma unroll 2
            for (; r + 16 <= Sreduce; r += 16) {
                T v0  = __ldcs(ptr + (r + 0)  * st_reduce);
                T v1  = __ldcs(ptr + (r + 1)  * st_reduce);
                T v2  = __ldcs(ptr + (r + 2)  * st_reduce);
                T v3  = __ldcs(ptr + (r + 3)  * st_reduce);
                T v4  = __ldcs(ptr + (r + 4)  * st_reduce);
                T v5  = __ldcs(ptr + (r + 5)  * st_reduce);
                T v6  = __ldcs(ptr + (r + 6)  * st_reduce);
                T v7  = __ldcs(ptr + (r + 7)  * st_reduce);
                T v8  = __ldcs(ptr + (r + 8)  * st_reduce);
                T v9  = __ldcs(ptr + (r + 9)  * st_reduce);
                T v10 = __ldcs(ptr + (r + 10) * st_reduce);
                T v11 = __ldcs(ptr + (r + 11) * st_reduce);
                T v12 = __ldcs(ptr + (r + 12) * st_reduce);
                T v13 = __ldcs(ptr + (r + 13) * st_reduce);
                T v14 = __ldcs(ptr + (r + 14) * st_reduce);
                T v15 = __ldcs(ptr + (r + 15) * st_reduce);
                m0  = v0  < m0  ? v0  : m0;
                m1  = v1  < m1  ? v1  : m1;
                m2  = v2  < m2  ? v2  : m2;
                m3  = v3  < m3  ? v3  : m3;
                m4  = v4  < m4  ? v4  : m4;
                m5  = v5  < m5  ? v5  : m5;
                m6  = v6  < m6  ? v6  : m6;
                m7  = v7  < m7  ? v7  : m7;
                m8  = v8  < m8  ? v8  : m8;
                m9  = v9  < m9  ? v9  : m9;
                m10 = v10 < m10 ? v10 : m10;
                m11 = v11 < m11 ? v11 : m11;
                m12 = v12 < m12 ? v12 : m12;
                m13 = v13 < m13 ? v13 : m13;
                m14 = v14 < m14 ? v14 : m14;
                m15 = v15 < m15 ? v15 : m15;
            }
            m0  = m1  < m0  ? m1  : m0;
            m2  = m3  < m2  ? m3  : m2;
            m4  = m5  < m4  ? m5  : m4;
            m6  = m7  < m6  ? m7  : m6;
            m8  = m9  < m8  ? m9  : m8;
            m10 = m11 < m10 ? m11 : m10;
            m12 = m13 < m12 ? m13 : m12;
            m14 = m15 < m14 ? m15 : m14;
            m0  = m2  < m0  ? m2  : m0;
            m4  = m6  < m4  ? m6  : m4;
            m8  = m10 < m8  ? m10 : m8;
            m12 = m14 < m12 ? m14 : m12;
            m0 = m4 < m0 ? m4 : m0;
            m8 = m12 < m8 ? m12 : m8;
            minval = m0 < m8 ? m0 : m8;
            for (; r < Sreduce; ++r) {
                T v = __ldcs(ptr + r * st_reduce);
                minval = v < minval ? v : minval;
            }
        } else {
            minval = __ldcs(ptr);
            for (int64_t r = 1; r < Sreduce; ++r) {
                T v = __ldcs(ptr + r * st_reduce);
                minval = v < minval ? v : minval;
            }
        }
        int64_t yidx = outer * Sinner_full + actual_inner;
        Y[yidx] = minval;
    }
}
// Vectorized variant: reads 4 contiguous elements of the inner
// dimension at a time using float4, cutting the number of load
// instructions (and loop iterations) by 4x for the dominant memory
// traffic of this reduction (repeated strided reads of X). Only used
// when the memory layout guarantees 16-byte alignment for the reads
// (inner stride 1, and both the outer and reduce strides are
// multiples of 4 elements). The (much smaller volume) output writes
// into Y are issued as plain scalar stores, so this kernel only
// handles the leading Sinner4*4 columns -- it does not require the
// full inner extent (or the output row length) to be a multiple of
// 4; any leftover 0-3 tail columns are handled separately by the
// scalar kernel so every input layout benefits from vectorized reads
// for the bulk of the data.
__global__ void min_reduce_kernel_vec4(
    const float* __restrict__ X,
    float* __restrict__ Y,
    int64_t Souter, int64_t Sreduce, int64_t Sinner4, int64_t Sinner_full,
    int64_t st_outer, int64_t st_reduce)
{
    int64_t total = Souter * Sinner4;
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)gridDim.x * blockDim.x;
    for (; idx < total; idx += stride) {
        int64_t outer = idx / Sinner4;
        int64_t inner4 = idx - outer * Sinner4;
        int64_t base = outer * st_outer + inner4 * 4;
        const float4* __restrict__ ptr = reinterpret_cast<const float4*>(X + base);
        float4 minv = __ldcs(ptr);
        int64_t r_stride4 = st_reduce / 4;
        for (int64_t r = 1; r < Sreduce; ++r) {
            const float4* __restrict__ vp = ptr + r * r_stride4;
            float4 v = __ldcs(vp);
            minv.x = v.x < minv.x ? v.x : minv.x;
            minv.y = v.y < minv.y ? v.y : minv.y;
            minv.z = v.z < minv.z ? v.z : minv.z;
            minv.w = v.w < minv.w ? v.w : minv.w;
        }
        int64_t ybase = outer * Sinner_full + inner4 * 4;
        // Scalar stores here (instead of a float4 store) since Y's row
        // length (Sinner_full) is not guaranteed to be a multiple of 4,
        // so outer*Sinner_full offsets are not guaranteed 16-byte
        // aligned; the write volume is tiny relative to the vectorized
        // reads above, so this has negligible performance impact.
        Y[ybase + 0] = minv.x;
        Y[ybase + 1] = minv.y;
        Y[ybase + 2] = minv.z;
        Y[ybase + 3] = minv.w;
    }
}
// Compute a grid size that avoids a partial "tail" wave of thread
// blocks. Using cudaOccupancyMaxActiveBlocksPerMultiprocessor we
// determine how many blocks of this kernel can be resident per SM
// simultaneously, multiply by the SM count to get the size of a
// full wave, and round the requested grid down to the nearest
// multiple of that wave size. The kernels already use a grid-stride
// loop, so any remaining work is simply covered by extra loop
// iterations instead of launching an uneven, partially-occupied
// final wave (which the profiler flagged as costing up to ~33% of
// total kernel runtime).
template <typename KernelFunc>
static int64_t wave_aligned_grid(KernelFunc kernel, int threads, int64_t blocks_needed, int64_t max_blocks) {
    int device = 0;
    cudaGetDevice(&device);
    int sm_count = 0;
    cudaDeviceGetAttribute(&sm_count, cudaDevAttrMultiProcessorCount, device);
    int max_active_blocks = 0;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(&max_active_blocks, kernel, threads, 0);
    int64_t wave_size = (int64_t)sm_count * (int64_t)max_active_blocks;
    if (wave_size <= 0) wave_size = 1;
    int64_t num_blocks = blocks_needed < max_blocks ? blocks_needed : max_blocks;
    if (num_blocks > wave_size) {
        int64_t waves = num_blocks / wave_size;
        num_blocks = waves * wave_size;
    }
    if (num_blocks < 1) num_blocks = wave_size;
    return num_blocks;
}
torch::Tensor min_reduce_dim3(torch::Tensor x, int64_t dim) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat, "only float32 is supported");
    TORCH_CHECK(x.dim() == 3, "expected a 3D tensor");
    if (dim < 0) dim += x.dim();
    TORCH_CHECK(dim == 0 || dim == 1 || dim == 2, "dim must be 0, 1, or 2");
    // Keep behavior well-defined for arbitrary input strides by forcing
    // a contiguous layout before computing strides (per-call, not repeated).
    auto x_c = x.contiguous();
    int64_t S0 = x_c.size(0);
    int64_t S1 = x_c.size(1);
    int64_t S2 = x_c.size(2);
    int64_t st0 = x_c.stride(0);
    int64_t st1 = x_c.stride(1);
    int64_t st2 = 1;
    int64_t Souter, Sreduce, Sinner;
    int64_t st_outer, st_reduce, st_inner;
    std::vector<int64_t> out_shape;
    if (dim == 0) {
        Souter = S1; Sreduce = S0; Sinner = S2;
        st_outer = st1; st_reduce = st0; st_inner = st2;
        out_shape = {S1, S2};
    } else if (dim == 1) {
        Souter = S0; Sreduce = S1; Sinner = S2;
        st_outer = st0; st_reduce = st1; st_inner = st2;
        out_shape = {S0, S2};
    } else {
        Souter = S0; Sreduce = S2; Sinner = S1;
        st_outer = st0; st_reduce = st2; st_inner = st1;
        out_shape = {S0, S1};
    }
    auto y = torch::empty(out_shape, x.options());
    constexpr int Threads = 512;
    int64_t max_blocks = 65535LL * 32LL;
    dim3 block(Threads);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    // Vectorize the dominant reduction reads with float4 loads whenever
    // the memory layout allows 16-byte aligned access to X: the inner
    // dimension must be unit-strided, and both the outer and reduce
    // strides must be multiples of 4 elements. Unlike the original
    // implementation, this no longer requires the inner extent itself
    // to be a multiple of 4 -- output writes into Y are always plain
    // scalar stores (tiny volume compared to the reads), so any
    // leftover 0-3 tail columns are simply handled by the scalar
    // kernel below. This lets shapes such as an inner extent of 4095
    // (not a multiple of 4) still benefit from vectorized reads for
    // the overwhelming majority of the reduction traffic.
    bool can_vec4 = (st_inner == 1) &&
                    (st_reduce % 4 == 0) &&
                    (st_outer % 4 == 0);
    if (can_vec4) {
        uintptr_t addrX = reinterpret_cast<uintptr_t>(x_c.data_ptr<float>());
        can_vec4 = ((addrX % 16) == 0);
    }
    int64_t Sinner4 = can_vec4 ? (Sinner / 4) : 0;
    if (Sinner4 > 0) {
        int64_t total4 = Souter * Sinner4;
        int64_t blocks_needed4 = (total4 + Threads - 1) / Threads;
        int64_t num_blocks4 = wave_aligned_grid(min_reduce_kernel_vec4, Threads, blocks_needed4, max_blocks);
        dim3 grid4((unsigned)num_blocks4);
        min_reduce_kernel_vec4<<<grid4, block, 0, stream>>>(
            x_c.data_ptr<float>(),
            y.data_ptr<float>(),
            Souter, Sreduce, Sinner4, Sinner,
            st_outer, st_reduce
        );
    }
    int64_t tail_start = Sinner4 * 4;
    int64_t tail_count = Sinner - tail_start;
    if (tail_count > 0) {
        int64_t total = Souter * tail_count;
        int64_t blocks_needed = (total + Threads - 1) / Threads;
        // Cap the grid size and rely on the grid-stride loop inside the
        // kernel to cover the remaining elements; this keeps the launch
        // configuration robust for arbitrarily large tensors.
        int64_t num_blocks = wave_aligned_grid(min_reduce_kernel<float>, Threads, blocks_needed, max_blocks);
        dim3 grid((unsigned)num_blocks);
        min_reduce_kernel<float><<<grid, block, 0, stream>>>(
            x_c.data_ptr<float>(),
            y.data_ptr<float>(),
            Souter, Sreduce, tail_count, Sinner, tail_start,
            st_outer, st_reduce, st_inner
        );
    }
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "min_reduce_kernel launch failed: ", cudaGetErrorString(err));
    return y;
}
